<?php require_once __DIR__ . '/../includes/bootstrap.php'; require_role('admin');
if(request_method()==='POST'){ require_csrf(); if($_POST['mode']==='exam'){ $st=$pdo->prepare('INSERT INTO exams (title,class_name,exam_date) VALUES (:t,:c,:d)'); $st->execute(['t'=>sanitize_string($_POST['title']),'c'=>sanitize_string($_POST['class_name']),'d'=>$_POST['exam_date']]); } else { $st=$pdo->prepare('INSERT INTO marks (exam_id,student_id,subject_name,marks_obtained,max_marks) VALUES (:e,:s,:sub,:m,:x)'); $st->execute(['e'=>(int)$_POST['exam_id'],'s'=>(int)$_POST['student_id'],'sub'=>sanitize_string($_POST['subject_name']),'m'=>$_POST['marks_obtained'],'x'=>$_POST['max_marks']]); }}
$exams=$pdo->query('SELECT * FROM exams ORDER BY exam_date DESC')->fetchAll(); $students=$pdo->query('SELECT id,student_id FROM students ORDER BY id DESC LIMIT 100')->fetchAll();
include __DIR__ . '/../includes/header.php'; ?>
<section class="section"><div class="container"><div class="card-grid"><div class="glass card"><h2>Create Exam</h2><form method="post"><input type="hidden" name="_token" value="<?= csrf_token() ?>"><input type="hidden" name="mode" value="exam"><input class="form-control" name="title" placeholder="Term 1" required><br><input class="form-control" name="class_name" placeholder="Class"><br><input class="form-control" type="date" name="exam_date"><br><button class="btn">Save Exam</button></form></div><div class="glass card"><h2>Marks Entry</h2><form method="post"><input type="hidden" name="_token" value="<?= csrf_token() ?>"><input type="hidden" name="mode" value="marks"><select class="form-control" name="exam_id"><?php foreach($exams as $e): ?><option value="<?= $e['id'] ?>"><?= e($e['title']) ?></option><?php endforeach; ?></select><br><select class="form-control" name="student_id"><?php foreach($students as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['student_id']) ?></option><?php endforeach; ?></select><br><input class="form-control" name="subject_name" placeholder="Math"><br><input class="form-control" name="marks_obtained" placeholder="85"><br><input class="form-control" name="max_marks" value="100"><br><button class="btn">Save Marks</button></form></div></div></div></section>
